// src/persona/embeddingSearch.ts
var _articles = null;
function loadArticles(data) {
  _articles = data;
}
function getArticles() {
  if (!_articles) throw new Error("Articles not loaded. Call loadArticles() first.");
  return _articles;
}
function cosineSimilarity(a, b) {
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}
function tagMatchScore(article, queryTerms) {
  if (!queryTerms.length || !article.tags.length) return 0;
  const articleTags = article.tags.map((t) => t.toLowerCase());
  const matchCount = queryTerms.filter(
    (qt) => articleTags.some((at) => at.includes(qt) || qt.includes(at))
  ).length;
  return matchCount / Math.max(queryTerms.length, 1);
}
function recencyScore(dateStr) {
  const articleDate = new Date(dateStr).getTime();
  if (isNaN(articleDate)) return 0;
  const now = Date.now();
  const ageMs = now - articleDate;
  const ageDays = ageMs / (1e3 * 60 * 60 * 24);
  if (ageDays < 180) return 1;
  if (ageDays > 730) return 0;
  return 1 - (ageDays - 180) / 550;
}
function searchArticles(queryEmbedding, topK = 10, queryTerms = []) {
  const articles = getArticles();
  const results = articles.map((article) => {
    const score = cosineSimilarity(queryEmbedding, article.embedding);
    const tagBonus = tagMatchScore(article, queryTerms);
    const recencyBonus = recencyScore(article.date);
    const finalScore = score * 0.7 + tagBonus * 0.2 + recencyBonus * 0.1;
    return {
      article,
      score,
      tagMatchBonus: tagBonus,
      recencyBonus,
      finalScore
    };
  });
  return results.sort((a, b) => b.finalScore - a.finalScore).slice(0, topK);
}

// src/persona/personaPrompts.ts
function buildSystemPrompt(profile) {
  const beliefs = profile.coreBeliefs.map((b) => `- ${b}`).join("\n");
  const antiPatterns = profile.antiPatterns.map((a) => `- ${a}`).join("\n");
  const expertise = profile.topicExpertise.join(", ");
  const patterns = profile.thinkingPatterns.slice(0, 5).map((p) => `- ${p.pattern}`).join("\n");
  const signatures = profile.signaturePhrases.map((s) => `"${s}"`).join(", ");
  return `Sen ${profile.authorName} gibi dusunen ve konusan bir dijital pazarlama danismanisin. Sana sorulan sorulari ve verilen is verilerini ${profile.authorName}'in bakis acisiyla, dusunce bicimi ve uslubuyla degerlendirirsin.

## KIMLIK
${profile.worldview}

## DUSUNCE BICIMI
Sorulara su yontemlerle yaklasirsin:
${patterns}

## TEMEL INANCLAR
${beliefs}

## ILETISIM STILI
- Ton: ${profile.communicationStyle.tone}
- Kelime secimi: ${profile.communicationStyle.vocabulary}
- Cumle yapisi: ${profile.communicationStyle.sentenceStructure}
- Gecis kaliplari: ${profile.communicationStyle.favoriteTransitions.join(", ")}
- Imza ifadeler: ${signatures}

## UZMANLIK ALANLARI
${expertise}

## ASLA YAPMAYACAGIN SEYLER
${antiPatterns}

## KURALLAR
1. Yanitlarini her zaman ${profile.authorName}'in bakis acisiyla ver
2. Jenerik pazarlama tavsiyesi verme \u2014 provocatif, ozgun ve fikir sahibi ol
3. Sorulara dogrudan cevap ver, lafini dolandirma
4. Mumkunse blog yazilarindan referans ver ("Bir yazimda su konuya deginmistim..." gibi)
5. Kullanicinin is verilerini analiz ederken, sadece veriyi tekrarlama \u2014 o verinin ne anlama geldigini yorumla
6. Turkce yaz, dogal ve akici bir dille`;
}
function buildArticleContext(results) {
  if (results.length === 0) return "";
  const sections = [];
  const top3 = results.slice(0, 3);
  for (const { article, finalScore } of top3) {
    const content = article.isFullContent ? article.content_text.slice(0, 2e3) : article.excerpt;
    sections.push(
      `### "${article.title}" (Relevans: ${(finalScore * 100).toFixed(0)}%)
Tez: ${article.enrichment.thesis}
Prensip: ${article.enrichment.principleExtracted}
Uygulanabilir durumlar: ${article.enrichment.applicableSituations.join(", ")}
Ton: ${article.enrichment.emotionalTone}
${article.enrichment.keyQuotes.length > 0 ? `Onemli alintilar: ${article.enrichment.keyQuotes.map((q) => `"${q}"`).join(" | ")}` : ""}
Icerik onizleme: ${content}`
    );
  }
  const rest = results.slice(3, 10);
  if (rest.length > 0) {
    const summaries = rest.map(
      ({ article, finalScore }) => `- "${article.title}" (${(finalScore * 100).toFixed(0)}%): ${article.enrichment.thesis} | Prensip: ${article.enrichment.principleExtracted} | Metaforlar: ${article.enrichment.metaphors.join(", ")}`
    ).join("\n");
    sections.push(`### Ilgili Diger Yazilar
${summaries}`);
  }
  return `
## ILGILI BLOG YAZILARI
Asagidaki yazilarin icerigini ve felsefesini yanitlarinda kullan. Dogrudan alintilar yapabilir, yazilara referans verebilirsin.

${sections.join("\n\n")}`;
}
var MAX_HISTORY_MESSAGES = 12;
function buildConversationHistory(messages) {
  if (messages.length === 0) return "";
  const recent = messages.slice(-MAX_HISTORY_MESSAGES);
  const formatted = recent.map((m) => {
    const role = m.role === "user" ? "Kullanici" : "Danisman";
    const content = m.content.length > 500 ? m.content.slice(0, 500) + "..." : m.content;
    return `${role}: ${content}`;
  }).join("\n\n");
  return `
## SOHBET GECMISI
${formatted}`;
}
function assembleFullPrompt(profile, articleResults, history, userMessage, preferences) {
  const parts = [
    buildSystemPrompt(profile),
    buildArticleContext(articleResults),
    buildConversationHistory(history)
  ];
  if (preferences && preferences.length > 0) {
    parts.push(buildPreferencesBlock(preferences));
  }
  const system = parts.filter(Boolean).join("\n\n---\n\n");
  return { system, user: userMessage };
}
function buildPreferencesBlock(preferences) {
  const items = preferences.map((p) => `- ${p}`).join("\n");
  return `## KULLANICI TERCIHLERI
Kullanici daha once su geri bildirimleri vermistir. Yanitlarini buna gore ayarla:
${items}`;
}
function generateSuggestedQuestions(businessContext) {
  const generic = [
    "Bir markanin en buyuk korkusu ne olmali?",
    "Sektorun en buyuk yalani ne sence?",
    "Dijital pazarlamada en cok yapilan hata ne?",
    "Marka stratejisi neden onemli?",
    "Icerik pazarlamasinda neyi yanlis yapiyoruz?"
  ];
  if (!businessContext) return generic;
  return [
    `${businessContext.businessName} icin en buyuk stratejik firsat ne olabilir?`,
    `${businessContext.sector} sektorunde rakiplerden ayrilmanin en iyi yolu ne?`,
    `Bu markanin dijital varligi icin ilk 3 adim ne olmali?`,
    "Bir markanin en buyuk korkusu ne olmali?",
    "Dijital pazarlamada en cok yapilan hata ne?"
  ];
}

// src/persona/contextAssembler.ts
function assembleContext(profile, articleResults, history, userMessage, preferences) {
  const { system, user } = assembleFullPrompt(profile, articleResults, history, userMessage, preferences);
  const articlesUsed = articleResults.slice(0, 10).map((r) => ({
    id: r.article.id,
    title: r.article.title,
    relevanceScore: Math.round(r.finalScore * 100) / 100
  }));
  return { system, user, articlesUsed };
}
