// src/pipeline/geminiClient.ts
import { GoogleGenAI } from "@google/genai";
var MODEL_IDS = {
  flash: "gemini-2.0-flash",
  pro: "gemini-3-pro-preview"
};
var _client = null;
function getClient() {
  if (!_client) {
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) throw new Error("GEMINI_API_KEY not configured");
    _client = new GoogleGenAI({ apiKey });
  }
  return _client;
}
var PRO_MIN_OUTPUT_TOKENS = 16384;
function resolveMaxTokens(tier, requested, fallback = 4096) {
  const base = requested ?? fallback;
  return tier === "pro" ? Math.max(base, PRO_MIN_OUTPUT_TOKENS) : base;
}
async function generateText(tier, prompt, agentName, config) {
  const client = getClient();
  const result = await client.models.generateContent({
    model: MODEL_IDS[tier],
    contents: prompt,
    config: {
      temperature: config?.temperature ?? 0.7,
      topP: 0.9,
      maxOutputTokens: resolveMaxTokens(tier, config?.maxOutputTokens, 2048),
      ...tier === "pro" ? {} : { thinkingConfig: { thinkingBudget: 0 } }
    }
  });
  const text = result.text ?? "";
  if (!text) {
    throw new Error(`Agent "${agentName}" returned empty text response`);
  }
  return text.trim();
}
async function generateEmbedding(text) {
  const client = getClient();
  const result = await client.models.embedContent({
    model: "text-embedding-004",
    contents: text
  });
  const values = result.embeddings?.[0]?.values;
  if (!values || values.length === 0) {
    throw new Error("Embedding API returned empty result");
  }
  return values;
}

